"""Export an offline interactive view of the captured Orekit J2 histories."""
from pathlib import Path
import json,hashlib
import numpy as np
ROOT=Path(__file__).resolve().parent
rows=np.genfromtxt(ROOT/'orekit_30s.csv',delimiter=',',names=True,dtype=None,encoding='utf8');data=[]
for speed in (0.,2.5,12.448437,16.029):
 a=rows[(rows['model']=='J2')&(rows['relative_speed_m_s']==speed)]
 data.append({'u':speed,'states':[[round(float(a[k][i]),6)for k in ('x_m','y_m','z_m','vx_m_s','vy_m_s','vz_m_s')]for i in range(0,len(a))]})
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>VOLLEY — Orbit explorer</title><style>body{max-width:1000px;margin:30px auto;padding:0 20px;font:16px/1.5 system-ui,sans-serif;color:#222;background:#fff;overflow-wrap:anywhere}h1{font-size:30px;font-weight:600}canvas{width:100%;border:1px solid #ddd}input{width:65%;vertical-align:middle}button{font:inherit;padding:6px 16px;background:#fff;border:1px solid #555;border-radius:2px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:7px;border-bottom:1px solid #ddd;text-align:right}td:first-child,th:first-child{text-align:left}.note{font-size:14px;color:#444}</style><h1>Release-state orbit explorer</h1><p>Native Orekit 13.1.6, fixed-axis J2. Four prescribed relative release inputs from the same numerical initial position. Move the time control to compare full position and velocity differences at a common epoch.</p><p><button id="play">Play</button> <input aria-label="Time since release" id="time" type="range" min="0" max="1440" value="0" step="1"> <output id="clock"></output></p><canvas id="view" width="1000" height="560" aria-label="Computed orbit projected onto the initial orbital plane"></canvas><p class="note">Projection onto the initial orbital plane; distances in kilometres. The grey circle is a 6378.137 km reference sphere. Projection is not a clearance test. Traces use one-minute samples from the first 95 minutes; markers use the selected epoch; interpolation between displayed positions is not used.</p><table><thead><tr><th>Relative input (m/s)</th><th>Position difference (km)</th><th>Velocity difference (m/s)</th></tr></thead><tbody id="values"></tbody></table><p class="note">Differences are from the no-impulse reference at the selected epoch. Velocity differences include orbital direction after phasing; they are not the imparted release delta-v. They are not customer delivery errors or measurement accuracy. No atmosphere, host manoeuvres, hardware uncertainty or conjunction covariance is included. Original CSV: orekit_30s.csv. Source SHA-256: HASH.</p><script>const data=DATA;const colors=['#555555','#0072b2','#d55e00','#009e73'];const c=document.getElementById('view'),ctx=c.getContext('2d'),slider=document.getElementById('time');let timer=null;const inc=51.6*Math.PI/180;function xy(s){return [s[0]/1000,(s[1]*Math.cos(inc)+s[2]*Math.sin(inc))/1000]}function norm(v){return Math.sqrt(v.reduce((a,b)=>a+b*b,0))}function draw(){const k=+slider.value;document.getElementById('clock').textContent=(k/60).toFixed(2)+' h';ctx.clearRect(0,0,1000,560);ctx.fillStyle='#fff';ctx.fillRect(0,0,1000,560);const scale=230/7200,cx=500,cy=280;function pos(s){const [x,y]=xy(s);return [cx+x*scale,cy-y*scale]}ctx.beginPath();ctx.arc(cx,cy,6378.137*scale,0,Math.PI*2);ctx.fillStyle='#f0f0f0';ctx.fill();ctx.strokeStyle='#999';ctx.stroke();ctx.font='14px sans-serif';ctx.fillStyle='#333';ctx.fillText('Initial-plane X (km)',775,540);ctx.fillText('Initial-plane transverse direction (km)',20,22);for(let t=-6000;t<=6000;t+=3000){ctx.fillStyle='#777';ctx.fillText(t,cx+t*scale-16,cy+14);ctx.fillText(t,cx+6,cy-t*scale)}data.forEach((d,j)=>{ctx.beginPath();d.states.slice(0,96).forEach((s,i)=>{const p=pos(s);if(i)ctx.lineTo(...p);else ctx.moveTo(...p)});ctx.strokeStyle=colors[j];ctx.lineWidth=1;ctx.setLineDash([j===0?3:0,0]);ctx.stroke();const p=pos(d.states[k]);ctx.beginPath();ctx.arc(...p,5,0,Math.PI*2);ctx.fillStyle=colors[j];ctx.fill();ctx.fillText(d.u.toFixed(3)+' m/s',p[0]+8,p[1]+(j-1.5)*14)});document.getElementById('values').innerHTML=data.map(d=>{const a=d.states[k],b=data[0].states[k];return '<tr><td>'+d.u+'</td><td>'+(norm(a.slice(0,3).map((x,i)=>x-b[i]))/1000).toFixed(3)+'</td><td>'+norm(a.slice(3).map((x,i)=>x-b[i+3])).toFixed(3)+'</td></tr>'}).join('')}slider.oninput=draw;document.getElementById('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;document.getElementById('play').textContent='Play'}else{timer=setInterval(()=>{slider.value=(+slider.value+5)%1441;draw()},150);document.getElementById('play').textContent='Pause'}};draw();</script></html>'''
page=page.replace('DATA',json.dumps(data,separators=(',',':'))).replace('HASH',hashlib.sha256((ROOT/'orekit_30s.csv').read_bytes()).hexdigest())
(ROOT/'orbit-explorer.html').write_text(page)
print('Offline orbit explorer built from native CSV')
